import{_ as s,o as a,c as t,a2 as l}from"./chunks/framework.Boholvbs.js";const D=JSON.parse('{"title":"xsync-filter(1)","description":"Select files and preview a mirror with explicit deletion behavior.","frontmatter":{"title":"xsync-filter(1)","description":"Select files and preview a mirror with explicit deletion behavior.","manual":"xsync-filter(1)","manualName":"Filters & mirroring","sectionNumber":"1"},"headers":[],"relativePath":"filters.md","filePath":"filters.md"}'),o={name:"filters.md"};function n(c,e,r,i,d,p){return a(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="xsync-filter-1" tabindex="-1">xsync-filter(1) <a class="header-anchor" href="#xsync-filter-1" aria-label="Permalink to &quot;xsync-filter(1)&quot;">​</a></h1><div class="manual-deck"><strong>Filters &amp; mirroring</strong><p>Select files and preview a mirror with explicit deletion behavior.</p></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION {#description}&quot;">​</a></h2><p>Filters use first-match ordering. Include/exclude rules normally affect both the source list and deletion protection. Use quoted patterns so your shell does not expand them first.</p><h2 id="excludes" tabindex="-1">EXCLUDE AND INCLUDE <a class="header-anchor" href="#excludes" aria-label="Permalink to &quot;EXCLUDE AND INCLUDE {#excludes}&quot;">​</a></h2><div class="example-caption">Exclude generated and repository internals</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aP</span><span style="color:#DEDEDE;"> --exclude=&#39;node_modules/&#39;</span><span style="color:#DEDEDE;"> --exclude=&#39;.git/&#39;</span><span style="color:#DEDEDE;"> project/</span><span style="color:#DEDEDE;"> backup/</span></span></code></pre></div><div class="example-caption">Select text files while keeping directory traversal</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aP</span><span style="color:#DEDEDE;"> --include=&#39;*/&#39;</span><span style="color:#DEDEDE;"> --include=&#39;*.txt&#39;</span><span style="color:#DEDEDE;"> --exclude=&#39;*&#39;</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><p>The directory include comes first so xsync can descend into directories that contain matching files. <code>-m</code> prunes empty directory chains from the filtered source list.</p><h2 id="mirror" tabindex="-1">PREVIEW A MIRROR <a class="header-anchor" href="#mirror" aria-label="Permalink to &quot;PREVIEW A MIRROR {#mirror}&quot;">​</a></h2><div class="example-caption">Dry run — no writes or deletions</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-ani</span><span style="color:#DEDEDE;"> --delete</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><p>Inspect the itemized plan and the <code>would transfer …, delete …</code> summary. When the plan matches your intent, execute the same source and destination with <code>-n</code> removed.</p><div class="example-caption">Execute with an explicit deletion limit</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aiP</span><span style="color:#DEDEDE;"> --delete</span><span style="color:#DEDEDE;"> --max-delete=100</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><aside class="manual-note"><span>DELETION</span><p><code>--delete</code> removes destination entries absent from the selected source tree. Source I/O errors suppress deletion unless <code>--ignore-errors</code> is explicitly requested. Exceeding <code>--max-delete</code> exits with code 25.</p></aside><h2 id="sides" tabindex="-1">SOURCE AND RECEIVER RULES <a class="header-anchor" href="#sides" aria-label="Permalink to &quot;SOURCE AND RECEIVER RULES {#sides}&quot;">​</a></h2><div class="manual-table-wrap"><table><thead><tr><th scope="col">Rule</th><th scope="col">Applies to</th></tr></thead><tbody><tr><td><code>H / S</code></td><td>Hide/show entries in the source list</td></tr><tr><td><code>P / R</code></td><td>Protect/risk entries during destination deletion</td></tr><tr><td><code>+ / −</code></td><td>Include/exclude; normally both sides</td></tr></tbody></table></div><div class="example-caption">Protect a receiver-only directory</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aP</span><span style="color:#DEDEDE;"> --delete</span><span style="color:#DEDEDE;"> --filter=&#39;P local-notes/&#39;</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><p><code>--delete-excluded</code> makes unqualified include/exclude rules sender-only and allows excluded destination entries to be deleted. Explicit receiver protection still applies.</p><h2 id="merge" tabindex="-1">MERGE FILES <a class="header-anchor" href="#merge" aria-label="Permalink to &quot;MERGE FILES {#merge}&quot;">​</a></h2><div class="example-caption">Load per-directory .rsync-filter files</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aP</span><span style="color:#DEDEDE;"> -F</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><div class="example-caption">Exclude filter files and defer deletion</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-aP</span><span style="color:#DEDEDE;"> -FF</span><span style="color:#DEDEDE;"> --delete-after</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><p>A second <code>-F</code> excludes the merge files themselves. <code>--delete-after</code> reloads receiver rules from the updated tree after transfers finish, so newly transferred protection rules affect that deletion pass.</p><h2 id="file-lists" tabindex="-1">FILE LISTS <a class="header-anchor" href="#file-lists" aria-label="Permalink to &quot;FILE LISTS {#file-lists}&quot;">​</a></h2><div class="example-caption">Copy selected directory trees recursively</div><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki xsync-greyscale vp-code" tabindex="0"><code><span class="line"><span style="color:#DEDEDE;">xs </span><span style="color:#DEDEDE;">-arP</span><span style="color:#DEDEDE;"> --files-from=selected.txt</span><span style="color:#DEDEDE;"> src/</span><span style="color:#DEDEDE;"> dst/</span></span></code></pre></div><p>Each list entry is relative to the source root. Leading slashes refer to that root; <code>..</code> cannot escape it. Use <code>-0</code>/<code>--from0</code> for filenames or patterns containing newlines.</p>',32)])])}const y=s(o,[["render",n]]);export{D as __pageData,y as default};
